// STT Normalization & Request Pre-processing
const inputData = $json.body || $json;
let rawMsg = '';
if (inputData.messages && inputData.messages.length > 0) {
  rawMsg = inputData.messages[inputData.messages.length - 1].content;
} else if (inputData.message) {
  rawMsg = inputData.message;
}

let normalized = rawMsg.trim();
const textLower = normalized.toLowerCase();

// Intent Detection Logic
let intent = 'recommendation';
if (/salam|assalam|hello|hi|kaun|kon/i.test(textLower)) {
  intent = 'greeting';
} else if (/bye|khuda hafiz|allah hafiz|shukriya|thanks/i.test(textLower)) {
  intent = 'goodbye';
} else if (/reschedule|time change|postpone/i.test(textLower)) {
  intent = 'reschedule';
} else if (/cancel|mansookh/i.test(textLower)) {
  intent = 'cancel';
} else if (/book|booking|appointment|visit|schedule|meeting|email|mail|بک|وزٹ|سائیڈ|سکیجول|ای میل/i.test(textLower)) {
  intent = 'booking';
} else if (/noc|transfer|installment|document|legal|dha procedure/i.test(textLower)) {
  intent = 'rag';
}

// City Extraction
let city = null;
if (/lahore|لاہور/i.test(textLower)) city = 'Lahore';
else if (/islamabad|اسلام آباد/i.test(textLower)) city = 'Islamabad';
else if (/karachi|کراچی/i.test(textLower)) city = 'Karachi';

return [{
  json: {
    session_id: inputData.session_id || 'n8n_session_1',
    raw_message: rawMsg,
    normalized_message: normalized,
    intent: intent,
    extracted_city: city,
    user_email: 'samiworkspace11@gmail.com'
  }
}];

return [{
  json: {
    reply: 'Assalam-o-Alaikum sir! RealEstate Hub se Zara baat kar rahi hoon. Main aap ki kis tarah madad kar sakti hoon? Aap kaun se city (Lahore, Islamabad, ya Karachi) aur budget mein property dekh rahe hain?',
    intent: 'greeting'
  }
}];

return [{
  json: {
    reply: 'Bohat shukriya sir! RealEstate Hub se rabta karne ka shukriya. Apna khayal rakhyega, Allah Hafiz!',
    intent: 'goodbye'
  }
}];

// Response Formatter for Vapi OpenAI-Compatible Chat Completion Format
const lastReply = $json.reply || ($json.body && $json.body.reply) || 'Assalam-o-Alaikum sir! Main aap ki kis tarah madad kar sakti hoon?';
const createdTs = Math.floor(Date.now() / 1000);

return [{
  json: {
    id: 'chatcmpl-n8n-' + createdTs,
    object: 'chat.completion',
    created: createdTs,
    model: 'n8n-langgraph-agent',
    choices: [
      {
        index: 0,
        message: {
          role: 'assistant',
          content: lastReply
        },
        finish_reason: 'stop'
      }
    ],
    usage: {
      prompt_tokens: 50,
      completion_tokens: 30,
      total_tokens: 80
    }
  }
}];
